parameters.jsCode:
const wh = $('Webhook').first().json;
let b = wh.body || wh;

// La commande arrive parfois serialisee dans un champ confirmation, avec un
// signe egal en tete herite d'une expression n8n.
if (b.confirmation) {
  let s = typeof b.confirmation === 'string' ? b.confirmation.trim() : null;
  if (s && s.startsWith('=')) s = s.slice(1).trim();
  try {
    if (s) b = JSON.parse(s);
    else if (typeof b.confirmation === 'object') b = b.confirmation;
  } catch (e) {}
}

// Le contexte vient de l'application, plus de l'onglet Marchands : une
// feuille renommee ne casse plus la confirmation d'une commande.
const m = $('Contexte boutique').first().json || {};

const out = { ...b };
out.reference = b.reference || b.order_id || '';
out.phone = b.phone || b.chat_id || b.destinataire || '';
out.nom = b.nom || b.customer_name || 'Client';
out.total = b.total ?? b.total_price ?? 0;
out.slug = String(m.slug || '');
out.whatsapp_marchand = String(m.telephone || '');
out.nom_boutique = String(m.nom || '');

// Groupe de livreurs du marchand. Il etait lu mais jamais transmis a
// « Lancer livreurs », qui recevait donc null : Telegram repondait
// « chat not found » et aucun livreur n'etait alerte.
out.groupe_livreurs = String(m.groupe_livreurs || '');

// JID WhatsApp FIABLE du client : le chat qui parle au bot,
// sinon le telephone saisi normalise (0... -> 225...)
const telBrut = String(out.phone || '').trim();
out.whatsapp_client = String(b.chat_id || '').trim()
  || (telBrut.startsWith('0') ? '225' + telBrut : telBrut);

// CANAL REEL DU CLIENT. Les notifications partaient en dur sur WhatsApp,
// alors que le lien de confirmation vise le chat_id. Une commande passee sur
// Telegram voyait donc son lien expedie a WaSender comme si l'identifiant
// Telegram etait un numero : l'envoi echouait, le client ne recevait rien, ne
// confirmait jamais, et la commande restait en suspens en silence.
out.canal_client = String(b.canal || '').trim().toLowerCase() === 'telegram'
  ? 'telegram'
  : 'whatsapp';

out.destinataire_client = out.canal_client === 'telegram'
  ? String(b.chat_id || b.destinataire || '').trim()
  : out.whatsapp_client;

return [{ json: out }];

